import com.study.room.model.Reservation;

/** Controller mappings, binding, validation, redirects and error statuses through MockMvc. */
@SpringBootTest
class HttpTests {
    @Autowired
    WebApplicationContext context;
    @Autowired
    JdbcTemplate jdbc;
    MockMvc mvc;

    @BeforeEach
    void setUp() {
        mvc = MockMvcBuilders.webAppContextSetup(context).build();
        jdbc.update("DELETE FROM room_reservation");
        jdbc.update("INSERT INTO room_reservation (room_id, member_name, people) VALUES (1, '김하나', 2), (1, '이둘', 3), (2, '박셋', 2)");
    }

    private int idOf(String name) {
        return jdbc.queryForObject("SELECT reservation_id FROM room_reservation WHERE member_name = ?", Integer.class, name);
    }

    @Test
    void listShowsEveryReservationAndTheRooms() throws Exception {
        mvc.perform(get("/reservations")).andExpect(status().isOk()).andExpect(view().name("reservation/list"))
                .andExpect(model().attributeExists("reservations", "rooms"));
        List<?> rows = (List<?>) mvc.perform(get("/reservations")).andReturn().getModelAndView().getModel().get("reservations");
        assertEquals(3, rows.size());
    }

    @Test
    void listKeepsTheSearchConditionsInTheModel() throws Exception {
        var result = mvc.perform(get("/reservations").param("roomId", "1").param("keyword", "하나")).andExpect(status().isOk()).andReturn();
        assertEquals(1, ((List<?>) result.getModelAndView().getModel().get("reservations")).size());
        assertEquals(1, result.getModelAndView().getModel().get("roomId"));
        assertEquals("하나", result.getModelAndView().getModel().get("keyword"));
    }

    @Test
    void detailShowsTheReservationOrAnErrorStatus() throws Exception {
        mvc.perform(get("/reservations/" + idOf("이둘"))).andExpect(status().isOk()).andExpect(view().name("reservation/detail"))
                .andExpect(model().attributeExists("reservation"));
        mvc.perform(get("/reservations/999999")).andExpect(status().isNotFound()).andExpect(view().name("error/not-found"));
        mvc.perform(get("/reservations/abc")).andExpect(status().isBadRequest());
    }

    @Test
    void invalidInputGoesBackToTheFormWithoutSaving() throws Exception {
        mvc.perform(post("/reservations").param("roomId", "1").param("memberName", " ").param("people", "0"))
                .andExpect(status().isOk()).andExpect(view().name("reservation/form"))
                .andExpect(model().attributeHasFieldErrors("form", "memberName", "people")).andExpect(model().attributeExists("rooms"));
        assertEquals(3, jdbc.queryForObject("SELECT COUNT(*) FROM room_reservation", Integer.class));
    }

    @Test
    void validInputRedirectsToTheDetailWithAFlashMessage() throws Exception {
        mvc.perform(post("/reservations").param("roomId", "3").param("memberName", "최넷").param("people", "4"))
                .andExpect(status().isFound()).andExpect(redirectedUrlPattern("/reservations/*")).andExpect(flash().attribute("message", "예약했습니다"));
        assertEquals(4, jdbc.queryForObject("SELECT COUNT(*) FROM room_reservation", Integer.class));
    }

    @Test
    void tooManyPeopleIsAConflictAndNothingIsSaved() throws Exception {
        mvc.perform(post("/reservations").param("roomId", "2").param("memberName", "정여섯").param("people", "3"))
                .andExpect(status().isConflict()).andExpect(view().name("error/full"));
        assertEquals(3, jdbc.queryForObject("SELECT COUNT(*) FROM room_reservation", Integer.class));
    }

    @Test
    void cancelRedirectsToTheListAndAMissingOneIsNotFound() throws Exception {
        int id = idOf("박셋");
        mvc.perform(post("/reservations/" + id + "/delete")).andExpect(status().isFound()).andExpect(redirectedUrl("/reservations"))
                .andExpect(flash().attribute("message", "예약을 취소했습니다"));
        mvc.perform(post("/reservations/" + id + "/delete")).andExpect(status().isNotFound());
        assertNotNull(context);
    }

    @Test
    void theRootRedirectsToTheList() throws Exception {
        mvc.perform(get("/")).andExpect(status().isFound()).andExpect(redirectedUrl("/reservations"));
    }

    @Test
    void theModelClassIsUsedForTheRows() throws Exception {
        List<?> rows = (List<?>) mvc.perform(get("/reservations")).andReturn().getModelAndView().getModel().get("reservations");
        assertEquals(Reservation.class, rows.get(0).getClass());
    }
}

package com.study.room;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.net.CookieManager;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.jdbc.core.JdbcTemplate;

/** The real embedded Tomcat renders the JSP pages and the redirects work for a browser with a session. */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class JspTests {
    @LocalServerPort
    int port;
    @Autowired
    JdbcTemplate jdbc;
    HttpClient client;

    @BeforeEach
    void setUp() {
        client = HttpClient.newBuilder().cookieHandler(new CookieManager()).followRedirects(HttpClient.Redirect.NORMAL).build();
        jdbc.update("DELETE FROM room_reservation");
        jdbc.update("INSERT INTO room_reservation (room_id, member_name, people) VALUES (1, '김하나', 2), (1, '이둘', 3), (2, '박셋', 2)");
    }

    private HttpResponse<String> get(String path) throws Exception {
        return client.send(HttpRequest.newBuilder(URI.create("http://localhost:" + port + path)).GET().build(),
                HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
    }

    private HttpResponse<String> post(String path, String form) throws Exception {
        return client.send(HttpRequest.newBuilder(URI.create("http://localhost:" + port + path))
                .header("Content-Type", "application/x-www-form-urlencoded; charset=UTF-8").POST(HttpRequest.BodyPublishers.ofString(form)).build(),
                HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
    }

    private int count(String text, String part) {
        return text.split(java.util.regex.Pattern.quote(part), -1).length - 1;
    }

    @Test
    void theListPageIsRenderedWithOneRowPerReservation() throws Exception {
        HttpResponse<String> response = get("/reservations");
        assertEquals(200, response.statusCode());
        assertTrue(response.headers().firstValue("Content-Type").orElse("").contains("text/html"));
        String body = response.body();
        assertTrue(body.contains("예약 목록") && body.contains("소회의실 A") && body.contains("김하나"));
        assertEquals(3, count(body, "<td><a href="));
        assertFalse(body.contains("${"), "EL must be evaluated");
    }

    @Test
    void theSearchShowsOnlyMatchingRowsAndTheEmptyMessageWhenNothingMatches() throws Exception {
        String one = get("/reservations?roomId=2").body();
        assertEquals(1, count(one, "<td><a href="));
        assertTrue(one.contains("박셋") && !one.contains("김하나"));
        String none = get("/reservations?keyword=nobody").body();
        assertTrue(none.contains("예약이 없습니다."));
        assertEquals(0, count(none, "<td><a href="));
    }

    @Test
    void valuesAreEscapedByCOut() throws Exception {
        jdbc.update("INSERT INTO room_reservation (room_id, member_name, people) VALUES (3, '<b>x</b>', 1)");
        String body = get("/reservations").body();
        assertTrue(body.contains("&lt;b&gt;x&lt;/b&gt;"));
        assertFalse(body.contains("<b>x</b>"));
    }

    @Test
    void theDetailPageShowsTheReservationAndACancelForm() throws Exception {
        int id = jdbc.queryForObject("SELECT reservation_id FROM room_reservation WHERE member_name = '이둘'", Integer.class);
        HttpResponse<String> response = get("/reservations/" + id);
        assertEquals(200, response.statusCode());
        String body = response.body();
        assertTrue(body.contains("예약 상세") && body.contains("이둘") && body.contains("소회의실 A"));
        assertTrue(body.contains("method=\"post\"") && body.contains("/reservations/" + id + "/delete"));
    }

    @Test
    void aMissingReservationShowsTheNotFoundPageWith404() throws Exception {
        HttpResponse<String> response = get("/reservations/999999");
        assertEquals(404, response.statusCode());
        assertTrue(response.body().contains("찾을 수 없습니다"));
    }

    @Test
    void theFormListsTheRoomsAndKeepsTheInputWhenValidationFails() throws Exception {
        String form = get("/reservations/new").body();
        assertEquals(3, count(form, "<option value="));
        HttpResponse<String> invalid = post("/reservations", "roomId=1&memberName=&people=0");
        assertEquals(200, invalid.statusCode());
        assertTrue(invalid.body().contains("예약자 이름을 입력하세요") && invalid.body().contains("인원은 1명 이상입니다"));
        assertEquals(3, jdbc.queryForObject("SELECT COUNT(*) FROM room_reservation", Integer.class));
    }

    @Test
    void aSuccessfulReservationEndsOnTheDetailPageWithTheFlashMessageOnce() throws Exception {
        HttpResponse<String> done = post("/reservations", "roomId=3&memberName=%EC%B5%9C%EB%84%B7&people=4");
        assertEquals(200, done.statusCode());
        HttpResponse<String> redirect = done.previousResponse().orElseThrow();
        assertEquals(302, redirect.statusCode());
        String location = redirect.headers().firstValue("Location").orElse("");
        // The first response of a new session may carry ;jsessionid in the Location.
        assertTrue(location.matches(".*/reservations/\\d+(;jsessionid=\\w+)?"), location);
        assertTrue(done.body().contains("예약했습니다") && done.body().contains("최넷"));
        HttpResponse<String> again = get(URI.create(location.replaceAll(";.*$", "")).getPath());
        assertFalse(again.body().contains("예약했습니다"), "the flash message is shown once");
        assertEquals(4, jdbc.queryForObject("SELECT COUNT(*) FROM room_reservation", Integer.class));
    }

    @Test
    void tooManyPeopleShowsTheConflictPage() throws Exception {
        HttpResponse<String> response = post("/reservations", "roomId=2&memberName=%EC%A0%95&people=3");
        assertEquals(409, response.statusCode());
        assertTrue(response.body().contains("예약할 수 없습니다"));
    }

    @Test
    void cancelingRedirectsToTheListWithTheMessage() throws Exception {
        int id = jdbc.queryForObject("SELECT reservation_id FROM room_reservation WHERE member_name = '박셋'", Integer.class);
        HttpResponse<String> response = post("/reservations/" + id + "/delete", "");
        assertEquals(200, response.statusCode());
        assertEquals(302, response.previousResponse().orElseThrow().statusCode());
        assertTrue(response.previousResponse().get().headers().firstValue("Location").orElse("").matches(".*/reservations(;jsessionid=\\w+)?"));
        assertTrue(response.body().contains("예약을 취소했습니다") && !response.body().contains("박셋"));
    }
}

package com.study.room;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.List;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.annotation.Transactional;

import com.study.room.exception.ReservationNotFoundException;
import com.study.room.exception.RoomFullException;
import com.study.room.mapper.ReservationMapper;
import com.study.room.model.Reservation;
import com.study.room.model.ReservationForm;
import com.study.room.model.StudyRoom;
import com.study.room.service.ReservationService;

/** The service rules without a database. */
class UnitTests {
    ReservationMapper mapper;
    ReservationService service;

    @BeforeEach
    void setUp() {
        mapper = mock(ReservationMapper.class);
        service = new ReservationService(mapper);
    }

    private StudyRoom room(int id, int capacity) {
        StudyRoom room = new StudyRoom();
        room.setRoomId(id);
        room.setRoomName("방" + id);
        room.setCapacity(capacity);
        return room;
    }

    private ReservationForm form(int roomId, int people) {
        ReservationForm form = new ReservationForm();
        form.setRoomId(roomId);
        form.setMemberName("김하나");
        form.setPeople(people);
        return form;
    }

    @Test
    void detailReturnsTheFoundReservation() {
        Reservation found = new Reservation();
        found.setReservationId(3);
        when(mapper.findById(3)).thenReturn(found);
        assertEquals(3, service.detail(3).getReservationId());
    }

    @Test
    void detailThrowsWhenNothingIsFound() {
        when(mapper.findById(9)).thenReturn(null);
        assertThrows(ReservationNotFoundException.class, () -> service.detail(9));
    }

    @Test
    void reserveStoresWhenThereIsRoomAndReturnsTheGeneratedKey() {
        when(mapper.findRoom(1)).thenReturn(room(1, 6));
        when(mapper.sumPeople(1)).thenReturn(2);
        when(mapper.insert(any(Reservation.class))).thenAnswer(call -> {
            call.<Reservation>getArgument(0).setReservationId(7);
            return 1;
        });
        assertEquals(7, service.reserve(form(1, 4)));
    }

    @Test
    void reserveRejectsMoreThanTheRemainingSeatsWithoutStoring() {
        when(mapper.findRoom(1)).thenReturn(room(1, 6));
        when(mapper.sumPeople(1)).thenReturn(2);
        assertThrows(RoomFullException.class, () -> service.reserve(form(1, 5)));
        verify(mapper, never()).insert(any(Reservation.class));
    }

    @Test
    void reserveRejectsAnUnknownRoom() {
        when(mapper.findRoom(anyInt())).thenReturn(null);
        assertThrows(IllegalArgumentException.class, () -> service.reserve(form(8, 1)));
        verify(mapper, never()).insert(any(Reservation.class));
    }

    @Test
    void cancelThrowsWhenNoRowWasDeleted() {
        when(mapper.delete(5)).thenReturn(0);
        assertThrows(ReservationNotFoundException.class, () -> service.cancel(5));
        when(mapper.delete(6)).thenReturn(1);
        service.cancel(6);
        verify(mapper).delete(6);
    }

    @Test
    void dtoSupportsBuilderConstructorsAndAccessors() {
        Reservation reservation = Reservation.builder().reservationId(3).roomId(1).roomName("A").memberName("민수").people(2).build();
        assertEquals(3, reservation.getReservationId());
        assertEquals("A", reservation.getRoomName());
        Reservation fromConstructor = new Reservation(3, 1, "A", "민수", 2);
        assertEquals("민수", fromConstructor.getMemberName());
        reservation.setPeople(4);
        assertEquals(4, reservation.getPeople());
    }

    @Test
    void listingDelegatesToMapperInAReadOnlyTransaction() throws Exception {
        Transactional transaction = ReservationService.class.getMethod("search", Integer.class, String.class).getAnnotation(Transactional.class);
        assertTrue(transaction != null && transaction.readOnly());
        List<Reservation> rows = List.of(new Reservation());
        when(mapper.search(2, "민")).thenReturn(rows);
        assertEquals(rows, service.search(2, "민"));
    }

    @Test
    void changingMethodsAreTransactional() throws Exception {
        assertTrue(ReservationService.class.getMethod("reserve", ReservationForm.class).isAnnotationPresent(Transactional.class));
        assertTrue(ReservationService.class.getMethod("cancel", int.class).isAnnotationPresent(Transactional.class));
    }
}
